import numpy as np
from scipy.optimize import minimize, brentq
import time

_state = {}

class _TimeLimit:
    def __init__(self, deadline):
        self.deadline = deadline
    def check(self):
        if time.time() > self.deadline:
            raise TimeoutError()
    def remaining(self):
        return max(0.0, self.deadline - time.time())

def evaluate_exact(h):
    n = len(h)
    dx = 2.0 / n
    corr = np.correlate(h, 1.0 - h, mode="full")
    return float(np.max(corr) * dx)

def project_feasible(h_raw, n):
    target = n / 2.0
    lo = float(np.min(h_raw)) - 2.0
    hi = 1.0 - float(np.max(h_raw)) + 2.0
    def _f(t):
        return float(np.sum(np.clip(h_raw + t, 0.0, 1.0))) - target
    lo_v = _f(lo)
    hi_v = _f(hi)
    if lo_v >= 0.0:
        return np.clip(h_raw, 0.0, 1.0)
    if hi_v <= 0.0:
        return np.clip(h_raw, 0.0, 1.0)
    t = brentq(_f, lo, hi, xtol=1e-14, rtol=1e-14, maxiter=200)
    return np.clip(h_raw + t, 0.0, 1.0)

def _smooth_obj(x):
    beta = _state['beta']
    n = _state['n']
    lim = _state['limit']
    lim.check()
    dx = 2.0 / n
    corr = np.correlate(x, 1.0 - x, mode="full") * dx
    bcorr = beta * corr
    m = np.max(bcorr)
    w = np.exp(bcorr - m)
    Z = np.sum(w)
    return float((m + np.log(Z)) / beta)

def _smooth_grad(x):
    beta = _state['beta']
    n = _state['n']
    lim = _state['limit']
    lim.check()
    dx = 2.0 / n
    corr = np.correlate(x, 1.0 - x, mode="full") * dx
    bcorr = beta * corr
    m = np.max(bcorr)
    w = np.exp(bcorr - m)
    Z = np.sum(w)
    p = w / Z
    grad = np.zeros(n)
    for k in range(2 * n - 1):
        d = k - (n - 1)
        wkt = p[k] * dx
        if d >= 0:
            if d < n:
                grad[d:] += wkt * (1.0 - x[:n - d])
            if (n - d) > 0:
                grad[:n - d] += wkt * (-x[d:])
        else:
            pp = -d
            if pp < n:
                grad[:n - pp] += wkt * (1.0 - x[pp:])
            if (n - pp) > 0:
                grad[pp:] += wkt * (-x[:n - pp])
    return grad

def _con_eq(x):
    n = _state['n']
    return float(np.sum(x)) - n / 2.0

def smooth_optimize(h0, n, limit, betas, maxiter):
    best_h = h0.copy()
    best_score = evaluate_exact(h0)
    bounds = [(0.0, 1.0)] * n
    constraints = [{'type': 'eq', 'fun': _con_eq}]
    current = best_h.copy()
    _state['n'] = n
    _state['limit'] = limit
    for beta in betas:
        if limit.remaining() < 5.0:
            break
        _state['beta'] = float(beta)
        try:
            res = minimize(_smooth_obj, current, jac=_smooth_grad,
                           method='SLSQP', bounds=bounds,
                           constraints=constraints,
                           options={'maxiter': maxiter, 'ftol': 1e-13})
            if res.x is not None and np.all(np.isfinite(res.x)):
                candidate = project_feasible(res.x, n)
                score = evaluate_exact(candidate)
                if score < best_score - 1e-12:
                    best_h = candidate.copy()
                    best_score = score
                current = candidate.copy()
        except (TimeoutError, Exception):
            break
    return best_h, best_score

def _active_lag_gradient(h, n):
    dx = 2.0 / n
    corr = np.correlate(h, 1.0 - h, mode="full") * dx
    k_max = int(np.argmax(corr))
    d = k_max - (n - 1)
    grad = np.zeros(n)
    if d >= 0:
        if d < n:
            grad[d:] += dx * (1.0 - h[:n - d])
        if (n - d) > 0:
            grad[:n - d] += dx * (-h[d:])
    else:
        pp = -d
        if pp < n:
            grad[:n - pp] += dx * (1.0 - h[pp:])
        if (n - pp) > 0:
            grad[pp:] += dx * (-h[:n - pp])
    return grad

def coordinate_refine(h0, n, limit, max_rounds):
    best_h = h0.copy()
    best_score = evaluate_exact(h0)
    no_improve = 0
    rng = np.random.RandomState(42)
    for rnd in range(max_rounds):
        if limit.remaining() < 3.0:
            break
        if no_improve > 300:
            break
        ag = _active_lag_gradient(best_h, n)
        if rnd < 30:
            pairs = []
            for i in range(n):
                for j in range(i + 1, n):
                    pairs.append((i, j))
        else:
            pairs = []
            for _ in range(n * (n - 1) // 2):
                i = int(rng.randint(n))
                j = int(rng.randint(n))
                if i != j:
                    pairs.append((min(i, j), max(i, j)))
        pair_grad_diff = np.array([abs(ag[p[0]] - ag[p[1]]) for p in pairs])
        order = np.argsort(-pair_grad_diff)
        improved = False
        for idx in order:
            if limit.remaining() < 3.0:
                break
            if no_improve > 300:
                break
            i, j = pairs[idx]
            for direction in (1, -1):
                if direction == 1:
                    lo_d = max(-best_h[j], -0.5)
                    hi_d = min(1.0 - best_h[i], 0.5)
                else:
                    lo_d = max(-best_h[i], -0.5)
                    hi_d = min(1.0 - best_h[j], 0.5)
                if hi_d - lo_d < 1e-12:
                    continue
                deltas = np.linspace(lo_d, hi_d, 7)
                best_ld = 0.0
                best_ls = best_score
                for dv in deltas:
                    if abs(dv) < 1e-12:
                        continue
                    tmp = best_h.copy()
                    if direction == 1:
                        tmp[i] += dv
                        tmp[j] -= dv
                    else:
                        tmp[i] -= dv
                        tmp[j] += dv
                    sc = evaluate_exact(tmp)
                    if sc < best_ls:
                        best_ls = sc
                        best_ld = dv
                if best_ld != 0.0 and best_ls < best_score - 1e-12:
                    if direction == 1:
                        best_h[i] += best_ld
                        best_h[j] -= best_ld
                    else:
                        best_h[i] -= best_ld
                        best_h[j] += best_ld
                    best_h = project_feasible(best_h, n)
                    best_score = best_ls
                    improved = True
                    no_improve = 0
            if not improved:
                no_improve += 1
    return best_h, best_score

def transfer_resolution(h_old, new_n):
    m = len(h_old)
    old_x = np.linspace(0.0, 2.0, m, endpoint=False)
    new_x = np.linspace(0.0, 2.0, new_n, endpoint=False)
    h_new = np.interp(new_x, old_x, h_old)
    return project_feasible(h_new, new_n)

